/* ReVale Empresas. Financial truth, permissions, and tenant scope come from the server. */
(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = value => '$ '+Number(value||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  const searchText = value => String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const day = value => value?new Intl.DateTimeFormat('es-EC',{day:'numeric',month:'short',year:'numeric',timeZone:'America/Guayaquil'}).format(new Date(String(value).length===10?value+'T12:00:00Z':value)):'Sin fecha final';
  const dateTime = value => value?new Intl.DateTimeFormat('es-EC',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Guayaquil'}).format(new Date(value)):'—';
  const paths = {
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
    fork:'<path d="M5 3v7m3-7v7m3-7v7M5 7h6M8 10v11M19 3c-3 3-4 6-4 9h4m0-9v18"/>',
    qr:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><path d="M15 15h3v3h3v3h-6v-3m6-6v3M12 3v3M3 12h5m4-3v3h3"/>',
    history:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6m3-3v5l3 2"/>',
    user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',
    arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',
    back:'<path d="M19 12H5m5-5-5 5 5 5"/>',
    help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4.3 1.7c-.8.5-1.8 1.1-1.8 2.8M12 17h.01"/>',
    eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',
    eyeoff:'<path d="m3 3 18 18M10 5a12 12 0 0 1 12 7 18 18 0 0 1-3 4M6 6a18 18 0 0 0-4 6s3 7 10 7a12 12 0 0 0 5-1M10 10a3 3 0 0 0 4 4"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
    wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v11H5a3 3 0 0 1-3-3V6m18 7h-5v4h5"/>',
    pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0"/><circle cx="12" cy="10" r="2.5"/>',
    gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13m0-13H8a3 3 0 1 1 3-3Zm0 0h4a3 3 0 1 0-3-3Z"/>',
    search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',
    pizza:'<path d="m3 3 18 7-12 12Zm0 0c7-1 14 2 18 7"/><circle cx="10" cy="9" r="1"/><circle cx="10" cy="15" r="1"/><circle cx="15" cy="11" r="1"/>',
    fish:'<path d="M3 8v8l5-4Zm5 4c3-8 10-8 14 0-4 8-11 8-14 0M15 6l-2-3m2 15-2 3"/><circle cx="18" cy="11" r=".6"/>',
    plus:'<path d="M12 4v16M4 12h16"/>',
    return:'<path d="M4 8h10a6 6 0 0 1 0 12h-3M4 8l5-5M4 8l5 5"/>',
    close:'<path d="m6 6 12 12M6 18 18 6"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
    receipt:'<path d="M5 3v18l3-2 4 2 4-2 3 2V3l-3 2-4-2-4 2ZM9 9h6m-6 4h6m-6 4h3"/>',
    logout:'<path d="M9 4H4v16h5m6-4 4-4-4-4M8 12h11"/>',
    camera:'<path d="M4 6h4l2-3h4l2 3h4v15H4Z"/><circle cx="12" cy="13" r="4"/>',
    download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    refresh:'<path d="M20 8a9 9 0 0 0-16 0m16-5v5h-5M4 16a9 9 0 0 0 16 0M4 21v-5h5"/>',
    mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'
  };
  const icon = (name, cls='') => `<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24">${paths[name]||paths.info}</svg>`;
  paths.building='<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M9 21v-5h6v5M8 7h1m6 0h1M8 11h1m6 0h1"/>';
  paths.team='<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>';
  paths.chart='<path d="M4 3v18h17M8 16v-4m5 4V7m5 9v-7"/>';
  paths.bank='<path d="m3 8 9-5 9 5H3m1 13h16M6 11v7m6-7v7m6-7v7"/>';
  paths.pause='<path d="M8 5v14M16 5v14"/>';
  const frequency={monthly:'Mensual',biweekly:'Quincenal',weekly:'Semanal',one_time:'Una vez',custom:'Personalizada'};
  const rollover={no_rollover:'No acumulable',full_rollover:'Acumulable',capped_rollover:'Acumulación limitada'};
  const roleNames={admin:'Administración',finance:'Finanzas',hr:'Recursos Humanos',viewer:'Consulta'};
  const navs=[['home','home','Resumen'],['employees','team','Colaboradores'],['programs','gift','Beneficios'],['funding','wallet','Recargas'],['approvals','shield','Aprobaciones'],['reports','chart','Reportes'],['team','user','Equipo y permisos']];
  const state={data:null,view:navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'home',search:'',employeeFilter:'all',employeeProgram:'',employeeAccess:'all',fundingFilter:'all',report:null,reportFilter:{},loading:false,request:null,team:null,inbox:null,approvalFilter:'pending',sectionError:''};
  let toastTimer,sessionVersion=0;
  const initials=(first,last='')=>((String(first||'').split(' ')[0][0]||'')+(String(last||'').split(' ')[0][0]||'')).toUpperCase();
  const brand=()=>`<div class="brand"><img src="/empleados/revale-logo.webp" alt="ReVale"><span>Para<br>empresas.</span></div>`;
  const badge=(status)=>{const map={company_pending:['Por aprobar en empresa','wait'],company_rejected:['Rechazada en empresa','off'],company_cancelled:['Retirada','off'],active:['Activo',''],suspended:['Pausado','wait'],ended:['Finalizado','off'],pending:['Por validar','wait'],received:['Por acreditar','wait'],allocated:['Acreditada',''],cancelled:['Cancelada','off'],not_invited:['Por invitar','wait'],invited:['Invitación vigente','wait'],expired:['Invitación vencida','off'],activated:['Cuenta activada',''],awaiting_preparation:['En preparación','wait'],awaiting_transfer:['Por transferir','wait'],partial_funding:['Fondos parciales','wait'],awaiting_credit:['Por acreditar','wait'],partial_credit:['Acreditación parcial','wait'],credited:['Acreditada',''],approved:['Aprobado',''],reversed:['Devuelto','off']};const [label,cls]=map[status]||[status||'Pendiente','off'];return `<span class="badge ${cls}">${esc(label)}</span>`;};
  const field=(label,value)=>`<div class="detail-row"><span>${esc(label)}</span><b>${esc(value)}</b></div>`;
  const empty=(title,description,ico='receipt',cta='')=>`<div class="empty"><span class="empty-icon">${icon(ico)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${cta}</div>`;
  const notice=(message,warning=false)=>`<div class="notice ${warning?'warning':''}">${icon('info')}<span>${message}</span></div>`;
  const requestButton=(label='Preparar recarga')=>state.data?.capabilities.requestFunding?`<button class="btn green" data-action="fund-new">${icon('plus')}${label}</button>`:'';
  function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
  async function request(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(new Error(d.error||'No pudimos conectar. Intenta nuevamente.'),{status:r.status});return d;}
  const api=(action,query={})=>request('/api/employer?'+new URLSearchParams({action,...query}));
  const post=(action,body)=>request('/api/employer?action='+action,{method:'POST',body:JSON.stringify(body)});
  function handleError(error){if(error.status===401){sessionVersion++;state.data=null;state.request=null;close();renderLogin('Tu sesión terminó. Ingresa nuevamente.');return;}toast(error.message);}
  function show(title,html,wide=false){const d=$('sheet');d.classList.toggle('wide',wide);d.innerHTML=`<div class="sheet-head"><h2 id="sheet-title">${esc(title)}</h2><button class="round" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>${html}`;if(!d.open)d.showModal();}
  function close(){$('sheet').close();}
  function formError(error){if(error.status===401)return handleError(error);if($('form-error')){$('form-error').textContent=error.message;$('form-error').classList.remove('hidden');$('form-error').scrollIntoView({block:'nearest'});}else handleError(error);}
  async function submit(form,work){if(form.dataset.busy)return;form.dataset.busy='1';const button=form.querySelector('[type="submit"]');const before=button.innerHTML;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Guardando…';try{await work();}catch(e){formError(e);}finally{delete form.dataset.busy;if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML=before;}}}
  const formErrorSlot='<div id="form-error" class="error hidden" role="alert"></div>';

  function renderLogin(message=''){
    $('app').innerHTML=`<div class="login-shell business-login"><section class="login-story" aria-labelledby="login-title">
      <div class="login-topbar"><img class="login-logo" src="/empleados/revale-logo-green.webp" alt="ReVale"><span class="login-product"><i></i> ReVale Empresas</span></div>
      <div class="login-intro"><span class="login-eyebrow">UN EQUIPO BIEN CUIDADO</span><h1 id="login-title">Tu equipo,<br><span>mejor cada día.</span></h1><p>Beneficios que se disfrutan.<br>Una gestión que se siente fácil.</p></div>
      <div class="login-scene" aria-hidden="true"><span class="login-orbit"></span><span class="login-food">${icon('team')}</span><div class="login-pass"><div class="login-pass-top"><span>ReVale Empresas</span>${icon('gift')}</div><strong>Un beneficio.<br>Muchos buenos días.</strong><div class="login-pass-bottom"><span>CUIDA. CONECTA. ACOMPAÑA.</span>${icon('building')}</div></div><span class="login-sticker">Bien por<br>tu equipo <span>✳</span></span></div>
      <div class="login-story-foot"><span>${icon('team')} Lo bueno empieza con tu gente.</span><span class="login-spark" aria-hidden="true">✳</span></div></section>
      <main class="login-panel" id="main"><div class="login-panel-inner"><span class="login-welcome">EL ESPACIO DE TU EMPRESA</span><h2>Tu equipo empieza aquí.</h2><p class="login-description">Ingresa y haz que tus beneficios lleguen más lejos.</p><form id="login-form">
      <div class="login-field"><label for="email">Correo de trabajo</label><div class="login-input">${icon('mail')}<input id="email" type="email" inputmode="email" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="tu@empresa.com" required aria-describedby="login-error"></div></div>
      <div class="login-field"><label for="password">Contraseña</label><div class="login-input">${icon('lock')}<input id="password" type="password" autocomplete="current-password" placeholder="Tu contraseña" required aria-describedby="login-error"><button type="button" class="login-password" data-action="password" aria-label="Mostrar contraseña">${icon('eye')}</button></div></div>
      <div id="login-error" class="error ${message?'':'hidden'}" role="alert">${esc(message)}</div><button type="submit" class="btn full login-submit" id="login-submit">Entrar a ReVale Empresas ${icon('arrow')}</button></form>
      <div class="login-trust">${icon('shield')} Un acceso personal para cada administrador</div><button class="login-help" data-action="help">¿Necesitas una mano? ${icon('arrow')}</button><p class="login-signoff">El bienestar de tu equipo.<br><b>La tranquilidad de tenerlo claro.</b></p></div></main></div>`;
    $('login-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('login-submit');if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Ingresando…';$('login-error').classList.add('hidden');try{const access=await request('/api/employer-auth?action=login',{method:'POST',body:JSON.stringify({email:$('email').value,password:$('password').value})});if(access.next){location.assign(access.next);return;}await loadAll();}catch(error){if($('login-error')){$('login-error').textContent=error.message;$('login-error').classList.remove('hidden');}if(button.isConnected){button.disabled=false;button.removeAttribute('aria-busy');button.innerHTML='Entrar a ReVale Empresas '+icon('arrow');}}});
  }
  async function loadAll(){const version=sessionVersion;const data=await api('dashboard');if(version!==sessionVersion)return;state.data=data;state.team=null;state.inbox=null;render();if(state.view==='reports')await loadReport();if(['team','approvals'].includes(state.view))await loadGovernance();}
  function render(){if(!state.data)return;const d=state.data,p=d.principal,name=p.displayName||p.email,role=roleNames[p.role]||'Consulta';
    $('app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="company-card"><span>${icon('building')}</span><div><b>${esc(d.employer.name)}</b><small>${d.demo?'Cuenta de demostración':'ReVale Empresas'}</small></div></div><nav class="side-nav" aria-label="Navegación principal">${navs.map(([v,i,n])=>`<button class="nav-link ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-caption">${icon('gift')}Un beneficio para tu equipo.<br>Una buena decisión cada día.</div><button class="user-card" data-action="account"><span class="avatar green">${esc(initials(name.split(' ')[0],name.split(' ')[1]))}</span><span><b>${esc(name)}</b><small>${esc(role)}</small></span>${icon('chevron')}</button></div></aside>
      <div class="workspace"><header class="topbar"><div class="breadcrumbs">ReVale Empresas <span>/</span><b>${esc(navs.find(n=>n[0]===state.view)?.[2])}</b></div><div class="mobile-brand">${brand()}</div><div class="top-tools"><span class="today">${esc(day(new Date().toISOString()))}</span>${d.demo?'<span class="badge demo">Cuenta demo</span>':''}<button class="round" data-action="refresh" aria-label="Actualizar datos">${icon('refresh')}</button><button class="round" data-action="help" aria-label="Ayuda">${icon('help')}</button><button class="round avatar green" data-action="account" aria-label="Mi cuenta">${esc(initials(name.split(' ')[0],name.split(' ')[1]))}</button></div></header><main id="main">${view()}</main><div class="sync-note">Actualizado ${esc(dateTime(d.updatedAt))} · Hora de Ecuador</div></div><nav class="footer-nav" aria-label="Navegación móvil">${navs.filter(n=>['home','employees','funding','approvals'].includes(n[0])).map(([v,i,n])=>`<button class="${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}<button data-action="more-nav" class="${['team','programs','reports'].includes(state.view)?'active':''}">${icon('plus')}Más</button></nav></div>`;bindView();}
  function pageHead(kicker,title,description,actions=''){return `<div class="page-head"><div><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
  function metric(label,value,note,ico){return `<div class="metric"><div class="metric-top"><span>${esc(label)}</span>${icon(ico)}</div><div class="money">${esc(value)}</div><p>${esc(note)}</p></div>`;}
  function benefitMini(p){return `<div class="benefit-mini"><span class="benefit-symbol">${icon('fork')}</span><div class="benefit-copy"><h3>${esc(p.name)}</h3><p>${esc(frequency[p.allocation_frequency])} · ${Number(p.active_employees)} ${Number(p.active_employees)===1?'colaborador':'colaboradores'}</p></div><span class="money">${money(p.allocation_amount)}</span></div>`;}
  function activityLine(t){return `<div class="activity-line"><span class="activity-symbol">${icon(t.status==='reversed'?'return':'fork')}</span><div class="activity-copy"><b>${esc(t.merchant_name)}</b><small>${esc(t.first_name+' '+t.last_name)} · ${esc(day(t.approved_at))}</small></div><span class="money">${t.status==='reversed'?'Devuelto':money(t.amount)}</span></div>`;}
  function home(){const d=state.data,month=new Intl.DateTimeFormat('es-EC',{month:'long',timeZone:'America/Guayaquil'}).format(new Date()),n=d.stats.active_employees;
    return pageHead(d.employer.name,'Tu equipo, bien cuidado.','Todo lo que necesitas para acompañar sus buenos momentos.',`<button class="btn light" data-nav="reports">${icon('chart')}Ver reportes</button>${requestButton()}`)+`
    <div class="dashboard-grid"><section class="card overview-hero"><div><div class="hero-kicker">${icon('wallet')}Fondos por acreditar</div><div class="hero-value money">${money(d.funding.unallocated_cash)}</div><p class="hero-hint">Recibidos por ReVale y pendientes de asignación.</p></div><div class="hero-foot"><span>En cuentas de tu equipo<b class="money">${money(d.stats.visible_balance)}</b></span><button class="text-btn" data-nav="funding">Ver recargas ${icon('arrow')}</button></div></section>
    <section class="card team-card"><h2>Lo bueno también<br>se comparte.</h2><p>Tus beneficios acompañan a las personas que hacen crecer tu empresa.</p><div class="team-stats"><div><div class="team-number money">${n}</div><small>${n===1?'colaborador con beneficio':'colaboradores con beneficio'}</small></div><div class="team-faces">${[...new Map(d.employees.filter(e=>e.funding_ready).map(e=>[e.person_id,e])).values()].slice(0,3).map(e=>`<span class="avatar" title="${esc(e.first_name+' '+e.last_name)}">${esc(initials(e.first_name,e.last_name))}</span>`).join('')}</div><button class="team-link" data-nav="employees" aria-label="Ver colaboradores">${icon('arrow')}</button></div></section></div>
    <div class="metric-grid">${metric('Consumos de '+month,money(d.summary.spent),'Consumos aprobados, sin devoluciones.','fork')}${metric('Beneficios activos',String(d.stats.active_programs),'Programas para acompañar a tu equipo.','gift')}${metric('Recargas en proceso',String(d.funding.pending_requests),'Pendientes de validación o acreditación.','history')}</div>
    ${d.approvals.pending?`<div class="notice approval-notice">${icon('shield')}<span><b>${d.approvals.mine?d.approvals.mine+' decisiones esperan por ti':d.approvals.pending+' recargas en aprobación interna'}</b><br>Todo claro antes de dar el siguiente paso.</span><button class="text-btn" data-nav="approvals">Revisar aprobaciones ${icon('arrow')}</button></div>`:''}
    ${d.stats.pending_activation?`<div class="notice activation-notice">${icon('team')}<span><b>${d.stats.pending_activation} ${d.stats.pending_activation===1?'persona por activar su cuenta':'personas por activar su cuenta'}</b><br>Ayuda a tu equipo a empezar a disfrutar su beneficio.</span><button class="text-btn" data-action="pending-access">Revisar accesos ${icon('arrow')}</button></div>`:''}
    ${d.funding.pending_requests?`<div class="notice warning">${icon('info')}<span>Tienes ${d.funding.pending_requests} ${d.funding.pending_requests===1?'recarga en proceso':'recargas en proceso'}. <button class="text-btn" data-nav="funding" style="padding:0">Revisar estado ${icon('arrow')}</button></span></div>`:''}
    <div class="dashboard-grid section-gap"><div class="stack"><section class="card"><div class="card-head"><h2>Beneficios para tu gente</h2><button class="text-btn" data-nav="programs">Ver todos ${icon('arrow')}</button></div>${d.programs.filter(p=>p.active).map(benefitMini).join('')||empty('Tu primer beneficio empieza aquí.','Coordina con ReVale la activación del programa de tu empresa.','gift')}</section><section class="card flow-card"><h2>Una recarga. Muchos buenos días.</h2><p>Prepara el monto de tu equipo y sigue cada paso hasta que puedan disfrutarlo.</p><div class="flow-steps"><span class="flow-step"><b>1</b> Preparas</span>${icon('chevron')}<span class="flow-step"><b>2</b> Tu empresa aprueba</span>${icon('chevron')}<span class="flow-step"><b>3</b> ReVale acredita</span></div></section></div><section class="card"><div class="card-head"><h2>Buenos momentos recientes</h2><button class="text-btn" data-nav="reports">Ver todos ${icon('arrow')}</button></div>${d.recent.length?d.recent.map(activityLine).join(''):empty('Los primeros momentos están por llegar.','Aquí verás los consumos del mes de tus colaboradores.','fork')}</section></div>${d.stats.shared_balances?'<p class="balance-footnote">El saldo visible excluye cuentas compartidas con otras empresas. Los reportes contienen únicamente los consumos de tus programas.</p>':''}`;}
  function filteredEmployees(){return state.data.employees.filter(e=>(state.employeeFilter==='all'||e.status===state.employeeFilter)&&(state.employeeAccess==='all'||(state.employeeAccess==='pending'?e.access_status!=='activated':e.access_status===state.employeeAccess))&&(!state.employeeProgram||e.program_id===state.employeeProgram)&&searchText([e.first_name,e.last_name,e.email,e.person_identification,e.department,e.cost_center].join(' ')).includes(searchText(state.search)));}
  function employeeRows(){const rows=filteredEmployees();return rows.length?rows.map(e=>`<tr><td><div class="person"><span class="avatar">${esc(initials(e.first_name,e.last_name))}</span><div><button class="person-name" data-employee="${esc(e.enrollment_id)}">${esc(e.first_name+' '+e.last_name)}</button><small>${esc(e.email)}</small></div></div></td><td data-label="Beneficio">${esc(e.program_name)}</td><td data-label="Acceso">${badge(e.access_status)}</td><td data-label="Estado">${badge(e.status)}</td><td data-label="Saldo" class="right"><span class="money">${e.balance===null?'—':money(e.balance)}</span></td><td><button class="round" data-employee="${esc(e.enrollment_id)}" aria-label="Ver ${esc(e.first_name+' '+e.last_name)}">${icon('chevron')}</button></td></tr>`).join(''):`<tr><td class="empty-cell" colspan="6">${empty('No encontramos colaboradores.','Prueba con otro nombre, correo o filtro.','team')}</td></tr>`;}
  function employeesView(){const d=state.data;return pageHead('TU GENTE','Un equipo. Muchos buenos momentos.','Incorpora a tu equipo y acompaña sus primeros buenos momentos.',state.data.capabilities.manageEmployees?`<button class="btn light" data-action="employee-import">${icon('download')}Importar equipo</button><button class="btn green" data-action="employee-new">${icon('plus')}Añadir colaborador</button>`:'')+`<div class="toolbar"><div class="toolbar-left"><label class="search">${icon('search')}<input type="search" id="employee-search" aria-label="Buscar colaborador" placeholder="Nombre, correo o identificación" value="${esc(state.search)}"></label><select id="employee-program" class="filter-select" aria-label="Filtrar por beneficio"><option value="">Todos los beneficios</option>${d.programs.map(p=>`<option value="${esc(p.id)}" ${state.employeeProgram===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="employee-access" class="filter-select" aria-label="Filtrar por acceso">${[['all','Todos los accesos'],['pending','Pendientes de activar'],['activated','Cuentas activadas'],['expired','Invitaciones vencidas']].map(([v,n])=>`<option value="${v}" ${state.employeeAccess===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn light" data-action="export-employees">${icon('download')}Exportar</button></div><div class="chip-row">${[['all','Todos'],['active','Activos'],['suspended','Pausados'],['ended','Finalizados']].map(([v,n])=>`<button class="chip ${state.employeeFilter===v?'active':''}" data-employee-filter="${v}" aria-pressed="${state.employeeFilter===v}">${n}<small>${d.employees.filter(e=>v==='all'||e.status===v).length}</small></button>`).join('')}</div><section class="card table-card"><div class="table-scroll mobile-cards"><table class="table"><thead><tr><th>Colaborador</th><th>Beneficio</th><th>Acceso</th><th>Estado</th><th class="right">Saldo individual</th><th></th></tr></thead><tbody id="employee-rows">${employeeRows()}</tbody></table></div><div class="table-foot"><span id="employee-count">${filteredEmployees().length} vinculaciones</span><span>Los cambios quedan registrados.</span></div></section><p class="balance-footnote">El saldo corresponde a la cuenta individual del colaborador. Las recargas dependen de su elegibilidad vigente; una pausa conserva el historial y el saldo.</p>`;}
  function programsView(){return pageHead('BIENESTAR CON PROPÓSITO','Beneficios que se sienten.','Define las condiciones que hacen de ReVale un beneficio para tu equipo.')+`<div class="program-grid">${state.data.programs.map(p=>`<section class="card program-card"><div class="row between"><span class="benefit-symbol">${icon('fork')}</span>${badge(p.active?'active':'ended')}</div><h2>${esc(p.name)}</h2><p class="muted">Una buena mesa también es parte del bienestar.</p><div class="program-price money">${money(p.allocation_amount)} <small>/ colaborador</small></div><div class="program-facts"><div><span>Frecuencia de referencia</span><b>${esc(frequency[p.allocation_frequency])}</b></div><div><span>Colaboradores activos</span><b>${Number(p.active_employees)}</b></div><div><span>Política configurada</span><b>${esc(rollover[p.rollover_policy])}</b></div><div><span>Vigencia</span><b>${p.valid_until?esc(day(p.valid_until)):'Sin fecha final'}</b></div></div><div class="program-buttons">${state.data.capabilities.manageBenefits?`<button class="btn light" data-program="${esc(p.id)}">${icon('gift')}Configurar beneficio</button>`:''}<button class="text-btn" data-rules="${esc(p.id)}">Reglas de uso ${icon('arrow')}</button></div></section>`).join('')}<section class="program-help"><div>${icon('shield')}<h3>Las reglas claras<br>hacen todo más fácil.</h3><p>Define cuánto pueden consumir y en qué restaurantes. ReVale valida las reglas antes de aprobar cada pago.</p><button class="text-btn" data-action="help">Así funciona ${icon('arrow')}</button></div></section></div><div class="section-gap">${notice('El monto y la frecuencia sirven para preparar tus recargas. La acreditación se realiza después de verificar los fondos y completar la aprobación de ReVale.')}</div>`;}
  function fundingRows(){const rows=state.data.fundingList.funding.filter(f=>state.fundingFilter==='all'||f.progress===state.fundingFilter||(f.status===state.fundingFilter&&!['company_pending','company_rejected','company_cancelled'].includes(f.progress)));return rows.length?rows.map(f=>`<tr><td><button class="ref" data-funding="${esc(f.id)}">${esc(f.external_reference||'Recarga de beneficios')}</button><small>${esc(day(f.created_at))} · ${Number(f.employee_count)} colaboradores</small></td><td class="optional">${esc(f.program_name)}</td><td data-label="Solicitado" class="right"><span class="money">${money(f.amount)}</span></td><td data-label="Recibido neto" class="right"><span class="money">${money(f.cash_net)}</span></td><td data-label="Acreditado" class="right"><span class="money">${money(f.allocated_amount)}</span></td><td data-label="Estado">${badge(f.progress||f.status)}</td></tr>`).join(''):`<tr><td colspan="6" class="empty-cell">${empty('El próximo buen momento empieza contigo.',state.data.fundingList.funding.length?'No hay recargas con este estado.':'Prepara tu primera recarga y sigue su avance hasta la acreditación.','wallet',state.data.fundingList.funding.length?'':requestButton('Preparar primera recarga'))}</td></tr>`;}
  function fundingView(){const f=state.data.funding;return pageHead('FONDOS PARA TU EQUIPO','Recarga. Acompaña. Repite.','Cada paso visible, desde tu solicitud hasta el saldo de tus colaboradores.',`${state.data.capabilities.requestFunding&&state.data.fundingList.funding.some(b=>b.status!=='cancelled')?'<button class="btn light" data-action="fund-repeat-last">'+icon('history')+'Repetir última recarga</button>':''}${requestButton()}`)+`<div class="metric-grid">${metric('Fondos recibidos',money(f.cash_received),'Transferencias verificadas por ReVale.','bank')}${metric('Fondos acreditados',money(f.allocated_funding),'Asignados mediante solicitudes de recarga.','check')}${metric('Por acreditar',money(f.unallocated_cash),'Fondos recibidos, netos de devoluciones.','wallet')}</div><div class="chip-row">${[['all','Todas'],['company_pending','En aprobación'],['pending','Por transferir'],['received','Por acreditar'],['allocated','Acreditadas'],['company_rejected','Rechazadas'],['company_cancelled','Retiradas'],['cancelled','Canceladas']].map(([v,n])=>`<button class="chip ${state.fundingFilter===v?'active':''}" data-funding-filter="${v}" aria-pressed="${state.fundingFilter===v}">${n}</button>`).join('')}</div><section class="card table-card"><div class="table-scroll mobile-cards"><table class="table"><thead><tr><th>Recarga</th><th>Beneficio</th><th class="right">Solicitado</th><th class="right">Recibido neto</th><th class="right">Acreditado</th><th>Estado</th></tr></thead><tbody>${fundingRows()}</tbody></table></div><div class="table-foot"><span>${state.data.fundingList.funding.length} solicitudes cargadas</span>${state.data.fundingList.hasMore?'<button class="text-btn" data-action="more-funding">Cargar más</button>':'<span>Historial de tu empresa</span>'}</div></section><div class="section-gap">${notice('Tu empresa aprueba la solicitud. Después, ReVale verifica los fondos y completa sus controles para acreditar el beneficio.')}</div>`;}
  function reportRows(){const r=state.report;return r?.items.length?r.items.map(t=>`<tr><td><button class="ref" data-report="${esc(t.id)}">${esc(t.first_name+' '+t.last_name)}</button><small>${esc(dateTime(t.approved_at))}</small></td><td data-label="Restaurante">${esc(t.merchant_name)}<small>${esc(t.location_name||'')}</small></td><td class="optional">${esc(t.program_name)}</td><td data-label="Monto" class="right"><span class="money">${money(t.amount)}</span></td><td data-label="Estado">${badge(t.status)}</td><td data-label="Factura"><span class="badge ${t.invoice_status==='matched'?'':'wait'}">${t.invoice_status==='matched'?'Registrada':'Pendiente'}</span></td></tr>`).join(''):`<tr><td class="empty-cell" colspan="6">${empty('Este período está tranquilo.','No hay consumos registrados con estos filtros.','chart')}</td></tr>`;}
  function reportsView(){const r=state.report,d=state.data,q=Object.keys(state.reportFilter).length?state.reportFilter:d.period;return pageHead('INFORMACIÓN PARA DECIDIR','Todo claro, hasta el último consumo.','Consulta el uso de tus beneficios y descarga el detalle para tu equipo.')+`<form id="report-form" class="period-form"><label>Desde<input type="date" name="from" aria-label="Desde" required value="${esc(q.from)}"></label><label>Hasta<input type="date" name="to" aria-label="Hasta" required value="${esc(q.to)}"></label><label>Beneficio<select name="program_id" aria-label="Beneficio"><option value="">Todos los beneficios</option>${d.programs.map(p=>`<option value="${esc(p.id)}" ${q.program_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><button class="btn" type="submit">Aplicar filtros</button><button class="btn light export" type="button" data-action="export-report" ${!r?.items.length||state.loading?'disabled':''}>${icon('download')}Exportar CSV</button></form><div id="report-content">${state.loading?'<div class="empty"><span class="spinner"></span><p>Cargando tus reportes…</p></div>':r?`<div class="metric-grid">${metric('Consumos netos',money(r.summary.spent),'Aprobados, excluyendo consumos devueltos.','fork')}${metric('Personas que lo disfrutaron',String(r.summary.participating_employees),'Colaboradores con consumos aprobados.','team')}${metric('Facturas pendientes',String(r.summary.invoices_pending),'Consumos aprobados sin factura registrada.','receipt')}</div><section class="card table-card"><div class="table-scroll mobile-cards"><table class="table"><thead><tr><th>Colaborador / fecha</th><th>Restaurante</th><th>Beneficio</th><th class="right">Monto</th><th>Consumo</th><th>Factura</th></tr></thead><tbody>${reportRows()}</tbody></table></div><div class="table-foot"><span>${r.items.length} de ${r.summary.total} consumos</span>${r.hasMore?'<button class="text-btn" data-action="more-report">Cargar más</button>':'<span>Hora de Ecuador</span>'}</div></section><p class="report-note">El período corresponde a la fecha de aprobación del consumo. Los consumos devueltos se muestran por trazabilidad y no suman al total neto. El estado “Registrada” indica que el comercio registró la factura; este reporte no la reemplaza.</p>`:empty('No pudimos cargar el reporte.','Usa Aplicar filtros para intentarlo otra vez.','refresh')}</div>`;}
  function view(){return state.view==='team'?teamView():state.view==='approvals'?approvalsView():state.view==='employees'?employeesView():state.view==='programs'?programsView():state.view==='funding'?fundingView():state.view==='reports'?reportsView():home();}
  async function go(viewName){if(!navs.some(n=>n[0]===viewName))return;close();state.view=viewName;history.replaceState(null,'','#'+viewName);render();window.scrollTo(0,0);if(viewName==='reports'&&!state.report)await loadReport();if(['team','approvals'].includes(viewName))await loadGovernance();}
  async function loadReport(more=false){if(state.loading)return;state.loading=true;if(!more)state.report=null;if(state.view==='reports')render();const version=sessionVersion;try{const r=await api('reports',{...(Object.keys(state.reportFilter).length?state.reportFilter:state.data.period),...(more?{offset:state.report.nextOffset}:{})});if(version!==sessionVersion)return;state.report=more?{...r,items:[...state.report.items,...r.items]}:r;}catch(e){handleError(e);}finally{state.loading=false;if(state.data&&state.view==='reports')render();}}
  async function loadGovernance(more=false){
    const viewName=state.view,version=sessionVersion,filter=state.approvalFilter;
    state.sectionError='';
    try{
      const d=await api(viewName==='team'?'team':'approvals',viewName==='team'?{}:{filter,...(more?{offset:state.inbox?.nextOffset||0}:{})});
      if(version!==sessionVersion||viewName!==state.view||filter!==state.approvalFilter)return;
      if(viewName==='team')state.team=d;else state.inbox=more?{...d,items:[...state.inbox.items,...d.items]}:d;
    }catch(error){if(error.status===401)return handleError(error);state.sectionError=error.message;}
    if(state.data&&viewName===state.view)render();
  }
  function governanceLoading(){return `<section class="card">${state.sectionError?empty('No pudimos cargar este espacio.',state.sectionError,'info','<button class="btn light" data-action="governance-retry">Volver a intentar</button>'):'<div class="empty"><span class="spinner"></span><p>Preparando la información de tu empresa…</p></div>'}</section>`;}
  function policyCard(policy){return `<section class="card approval-policy"><div class="policy-title"><span class="benefit-symbol">${icon('shield')}</span><div><span class="eyebrow">REGLAS CLARAS</span><h2>Cada decisión,<br>en buenas manos.</h2></div></div><div class="policy-ranges"><div><span>Hasta ${money(policy.threshold)}</span><b>1 aprobación</b><small>De otra persona</small></div><div><span>Más de ${money(policy.threshold)}</span><b>2 aprobaciones</b><small>De personas diferentes</small></div></div><p>Administración y Finanzas pueden aprobar dentro de su límite. Quien prepara la recarga no puede aprobarla.</p>${state.data.capabilities.managePolicy?'<button class="text-btn" data-action="policy-edit">Configurar umbral '+icon('arrow')+'</button>':''}<small class="policy-version">Versión ${policy.version} · Los cambios aplican a nuevas solicitudes.</small></section>`;}
  const roleCopy={admin:'Gestiona accesos, reglas, beneficios y colaboradores. Prepara y aprueba recargas.',hr:'Gestiona colaboradores y beneficios. Prepara recargas para aprobación.',finance:'Prepara y aprueba recargas dentro de su límite. Consulta reportes.',viewer:'Consulta beneficios, colaboradores, recargas, aprobaciones y reportes.'};
  function teamView(){
    const head=pageHead('EQUIPO Y PERMISOS','Bien acompañados. Mejor organizados.','Cada persona con su acceso. Cada decisión con su responsable.',state.data.capabilities.manageTeam?'<button class="btn green" data-action="team-new">'+icon('plus')+'Invitar al equipo</button>':'');
    if(!state.team)return head+governanceLoading();const d=state.team,can=state.data.capabilities.manageTeam;
    return head+`<div class="governance-grid">${policyCard(d.policy)}<section class="card team-explainer"><span class="eyebrow">UN ESPACIO COMPARTIDO</span><h2>El bienestar se<br>gestiona en equipo.</h2><p>Recursos Humanos prepara el beneficio. Finanzas revisa los montos. ReVale verifica los fondos y acredita.</p><div class="role-pills"><span>${icon('team')} RR. HH.</span><span>${icon('shield')} Finanzas</span><span>${icon('check')} ReVale</span></div><small>Estos accesos administran la empresa. Los colaboradores activan su beneficio desde Mi ReVale.</small></section></div><section class="card table-card section-gap"><div class="card-head"><h2>Tu equipo administrador</h2><span class="badge">${d.members.filter(m=>m.active).length} accesos habilitados</span></div><div class="table-scroll mobile-cards"><table class="table"><thead><tr><th>Persona</th><th>Rol</th><th>Límite por aprobación</th><th>Acceso</th><th></th></tr></thead><tbody>${d.members.map(m=>`<tr><td><div class="person"><span class="avatar">${esc(initials(m.display_name))}</span><div><b>${esc(m.display_name)}${m.id===state.data.principal.employerUserId?' <span class="you-label">Tú</span>':''}</b><small>${esc(m.email)}</small></div></div></td><td data-label="Rol">${esc(roleNames[m.role]||m.role)}</td><td data-label="Límite">${['admin','finance'].includes(m.role)?m.approval_limit===null?'Sin límite personal':money(m.approval_limit):'No aprueba recargas'}</td><td data-label="Acceso">${badge(m.access_status)}</td><td>${can?`<button class="text-btn" data-member="${esc(m.id)}">Ver acceso ${icon('chevron')}</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function approvalsView(){
    const d=state.data,head=pageHead('APROBACIONES','Un paso más para tu equipo.','Revisa cada recarga, conoce quién debe actuar y deja tu decisión registrada.',requestButton());
    return head+`<div class="approval-overview"><section class="card approval-focus"><span class="eyebrow">TU BANDEJA</span><strong class="money">${d.approvals.mine}</strong><h2>${d.approvals.mine===1?'decisión espera por ti':'decisiones esperan por ti'}</h2><p>${d.approvals.mine?'Tu revisión acerca el beneficio a tu equipo.':'Cuando una recarga necesite tu revisión, la encontrarás aquí.'}</p></section><section class="card approval-explainer"><span class="benefit-symbol">${icon('shield')}</span><h2>Una revisión que da tranquilidad.</h2><p>Hasta ${money(d.policy.threshold)}, una aprobación independiente. Por encima, dos. La aprobación interna autoriza continuar con ReVale; la acreditación depende de los fondos y sus controles financieros.</p></section></div><div class="chip-row">${[['pending','Pendientes de empresa'],['mine','Me toca aprobar'],['history','Historial']].map(([v,n])=>`<button class="chip ${state.approvalFilter===v?'active':''}" data-approval-filter="${v}" aria-pressed="${state.approvalFilter===v}">${n}</button>`).join('')}</div>${!state.inbox?governanceLoading():`<section class="card approval-list">${state.inbox.items.length?state.inbox.items.map(a=>`<button class="approval-row" data-funding="${esc(a.funding_batch_id)}"><span class="approval-row-icon">${icon(a.status==='approved'?'check':'shield')}</span><span class="approval-row-copy"><b>${esc(a.external_reference||a.program_name)}</b><small>${esc(a.requester_name)} · ${esc(dateTime(a.created_at))}</small><span class="approval-count">${a.approved_count} de ${a.required_approvals} aprobaciones ${badge(a.funding_status==='cancelled'?'cancelled':a.status==='pending'?'company_pending':a.status==='rejected'?'company_rejected':a.status==='cancelled'?'company_cancelled':'approved')}</span></span><span class="money">${money(a.amount)}</span>${icon('chevron')}</button>`).join(''):empty(state.approvalFilter==='mine'?'Todo al día por aquí.':state.approvalFilter==='history'?'Cada decisión tendrá su lugar.':'Tu bandeja está al día.',state.approvalFilter==='mine'?'No tienes solicitudes pendientes que puedas aprobar.':state.approvalFilter==='history'?'Las solicitudes aprobadas, rechazadas o retiradas aparecerán aquí.':'Las próximas recargas aparecerán aquí para revisión.','shield')}${state.inbox.hasMore?'<div class="form-actions"><button class="btn light" data-action="more-approvals">Cargar más</button></div>':''}</section>`}`;
  }
  function memberForm(member=null){
    const editing=!!member,own=member?.id===state.data.principal.employerUserId;
    if(own){show('Tu acceso a la empresa',`<p class="sheet-sub">${esc(member.display_name)} · ${esc(member.email)}</p>${field('Rol',roleNames[member.role])}${field('Límite por aprobación',member.approval_limit===null?'Sin límite personal':money(member.approval_limit))}${notice('Otro administrador debe modificar tus permisos. Así, cada cambio de acceso tiene una revisión independiente.')}`);return;}
    show(editing?'Un acceso, bien definido.':'Suma a quien lo hace posible.',`<p class="sheet-sub">${editing?esc(member.display_name)+' · '+esc(member.email):'Invita a la persona que te ayudará a gestionar el beneficio.'}</p><form id="team-form">${!editing?'<label class="form-field">Nombre completo<input class="input" name="display_name" maxlength="100" minlength="2" required autocomplete="name"></label><label class="form-field">Correo de trabajo<input class="input" name="email" type="email" maxlength="254" required autocomplete="email"></label>':''}<label class="form-field">Rol<select class="input" name="role" id="team-role">${Object.entries(roleNames).map(([v,n])=>`<option value="${v}" ${v===(member?.role||'viewer')?'selected':''}>${n}</option>`).join('')}</select></label><div id="team-role-copy" class="role-description">${esc(roleCopy[member?.role||'viewer'])}</div><label class="form-field section-gap" id="team-limit-field">Límite por aprobación (USD)<input class="input" type="number" name="approval_limit" min="0" max="500000000" step="0.01" placeholder="Sin límite personal" value="${esc(member?.approval_limit??'')}"><small>Es el total máximo de cada recarga que puede aprobar. Vacío: sin límite personal. Cero: no puede aprobar.</small></label>${editing?`<label class="form-field">Estado<select class="input" name="active"><option value="true" ${member.active?'selected':''}>Habilitado</option><option value="false" ${!member.active?'selected':''}>Suspendido</option></select></label><label class="form-field">Motivo del cambio<textarea class="input" name="reason" minlength="5" maxlength="400" required placeholder="Deja el contexto para tu equipo"></textarea></label>`:notice('Se creará un enlace personal válido por 72 horas para compartir con esta persona. Elegirá su propia contraseña.')}<div id="team-admin-warning" class="section-gap">${notice('Administración puede invitar a otras personas y cambiar permisos y reglas de aprobación. Asigna este rol a quien deba tener esa responsabilidad.',true)}</div>${formErrorSlot}<div class="form-actions"><button type="button" class="btn light" data-action="close">Cancelar</button><button class="btn green" type="submit">${editing?'Guardar acceso':'Crear invitación'} ${icon(editing?'check':'mail')}</button></div></form>${editing&&member.active&&member.access_status!=='activated'?`<div class="section-gap">${notice('Al cambiar permisos, la invitación anterior vence. Genera una nueva con el acceso actualizado.')}<button class="btn light full" data-team-invite="${esc(member.id)}">${icon('mail')}Renovar invitación</button></div>`:''}`);
    const roleChange=()=>{const role=$('team-role').value;$('team-role-copy').textContent=roleCopy[role];$('team-limit-field').classList.toggle('hidden',!['admin','finance'].includes(role));$('team-admin-warning').classList.toggle('hidden',role!=='admin');};$('team-role').onchange=roleChange;roleChange();
    $('team-form').onsubmit=event=>{event.preventDefault();submit(event.target,async()=>{const values=Object.fromEntries(new FormData(event.target));if(editing){await post('update-team',{...values,user_id:member.id,version:member.access_version,active:values.active==='true'});await loadAll();close();toast('Acceso actualizado. El cambio quedó registrado.');}else await issueTeamInvite(values);});};
  }
  function editMember(id){const member=state.team?.members.find(m=>m.id===id);if(member)memberForm(member);}
  async function issueTeamInvite(body){const {invitation:i}=await post('invite-team',body);await loadAll();show('Su lugar ya está preparado.',`<div class="success-symbol">${icon('mail')}</div><p class="sheet-sub">Comparte este enlace con <b>${esc(i.display_name)}</b> en ${esc(i.email)} para activar su acceso.</p><label class="form-field">Invitación personal<input id="team-invitation-link" class="input reference-input" value="${esc(i.url)}" readonly></label>${field('Válida hasta',dateTime(i.expires_at))}${notice('El enlace se usa una sola vez. Si generaste uno nuevo, el anterior dejó de funcionar.')}<div class="form-actions"><button class="btn light" data-action="close">Cerrar</button><button class="btn green" data-action="copy-team-invitation">${icon('mail')}Copiar invitación</button></div>`);}
  function policyForm(){const p=state.team?.policy||state.data.policy;show('Las reglas, a tu medida.',`<p class="sheet-sub">Define desde qué monto se necesita una segunda mirada.</p><form id="policy-form"><label class="form-field">Hasta este monto, 1 aprobación (USD)<input class="input" type="number" name="threshold" min="0.01" step="0.01" max="500000000" required value="${p.threshold}"><small>Por encima de este monto, se requieren 2 personas diferentes.</small></label><label class="form-field">Motivo del cambio<textarea class="input" name="reason" minlength="5" maxlength="400" required placeholder="Ej.: nueva política de autorizaciones"></textarea></label>${notice('Las solicitudes existentes conservan la regla con la que se crearon. Quien prepara nunca puede aprobar su propia recarga.')}${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button class="btn green" type="submit">Guardar regla ${icon('check')}</button></div></form>`);$('policy-form').onsubmit=event=>{event.preventDefault();submit(event.target,async()=>{await post('update-approval-policy',{...Object.fromEntries(new FormData(event.target)),version:p.version});await loadAll();close();toast('Regla actualizada para nuevas solicitudes.');});};}
  function approvalBlock(a){
    if(!a)return '';state.activeApproval=a;
    const pending=a.status==='pending'&&a.funding_status!=='cancelled',labels={approve:'Aprobó',reject:'Rechazó',cancel:'Retiró'};
    return `<section class="approval-detail"><div class="row between"><h3>${icon('shield')}Aprobación de tu empresa</h3><span class="badge ${pending?'wait':''}">${a.approved_count} de ${a.required_approvals}</span></div><p class="approval-rule">Preparó ${esc(a.requester_name)} · Regla v${a.policy_version}: ${a.required_approvals} ${a.required_approvals===1?'aprobación':'aprobaciones'} para ${money(a.amount)}.</p><div class="decision-history"><div><span class="decision-dot"></span><p><b>Solicitud preparada</b><small>${esc(a.requester_name)} · ${esc(dateTime(a.created_at))}</small></p></div>${a.decisions.map(d=>`<div><span class="decision-dot ${d.decision==='approve'?'positive':'negative'}"></span><p><b>${labels[d.decision]} ${esc(d.actor_name)}</b><small>${esc(roleNames[d.actor_role]||d.actor_role)} · ${esc(dateTime(d.created_at))}</small>${d.note?`<span class="decision-note">${esc(d.note)}</span>`:''}</p></div>`).join('')}</div>${pending?`<div class="approval-waiting"><b>${a.blocked?'Hace falta completar el equipo aprobador':'La siguiente mirada'}</b><p>${a.eligible_approvers.length?'Pueden revisar: '+a.eligible_approvers.map(u=>esc(u.display_name)).join(', ')+'.':'Todavía no hay otra persona habilitada con límite suficiente.'} Faltan ${a.remaining_approvals} ${a.remaining_approvals===1?'aprobación':'aprobaciones'}.</p>${a.blocked&&state.data.capabilities.manageTeam?'<button class="text-btn" data-nav="team">Revisar equipo y permisos '+icon('arrow')+'</button>':''}</div>`:''}${pending&&a.requested_by===state.data.principal.employerUserId?'<p class="approval-rule">Tú preparaste esta solicitud. Otra persona debe aprobarla.</p>':''}${a.can_decide||a.can_cancel?`<div class="form-actions decision-actions">${a.can_cancel?'<button class="btn light" data-decision="cancel">Retirar solicitud</button>':''}${a.can_decide?'<button class="btn light" data-decision="reject">Rechazar</button><button class="btn green" data-decision="approve">'+icon('check')+'Aprobar recarga</button>':''}</div>`:''}</section>`;
  }
  function decisionForm(decision){const a=state.activeApproval;if(!a)return;const titles={approve:'Tu revisión hace la diferencia.',reject:'Deja claro qué debe cambiar.',cancel:'¿Retirar esta solicitud?'},buttons={approve:'Confirmar aprobación',reject:'Rechazar solicitud',cancel:'Confirmar retiro'};show(titles[decision],`<p class="sheet-sub">${esc(a.external_reference||a.program_name)} · Preparó ${esc(a.requester_name)}</p><div class="detail-total"><span>Total de la recarga</span><strong class="money">${money(a.amount)}</strong></div><form id="decision-form"><label class="form-field">${decision==='approve'?'Comentario (opcional)':'Motivo'}<textarea class="input" name="note" maxlength="600" ${decision==='approve'?'':'required minlength="5"'} placeholder="Contexto para el equipo"></textarea></label>${notice(decision==='approve'?'Tu decisión quedará registrada. Cuando se completen las aprobaciones internas, ReVale podrá continuar con la validación de fondos y sus controles financieros.':'Esta solicitud no continuará. El detalle y las decisiones se conservarán; puedes preparar una nueva recarga con los cambios.')}${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-funding="${esc(a.funding_batch_id)}">Volver al detalle</button><button class="btn ${decision==='approve'?'green':''}" type="submit">${buttons[decision]}</button></div></form>`);$('decision-form').onsubmit=event=>{event.preventDefault();submit(event.target,async()=>{await post('decide-funding',{id:a.funding_batch_id,decision,note:event.target.elements.note.value});await loadAll();await showFunding(a.funding_batch_id);toast('Decisión registrada.');});};}
  function bindView(){
    $('employee-search')?.addEventListener('input',e=>{state.search=e.target.value;$('employee-rows').innerHTML=employeeRows();$('employee-count').textContent=filteredEmployees().length+' vinculaciones';});
    $('employee-program')?.addEventListener('change',e=>{state.employeeProgram=e.target.value;$('employee-rows').innerHTML=employeeRows();$('employee-count').textContent=filteredEmployees().length+' vinculaciones';});
    $('employee-access')?.addEventListener('change',e=>{state.employeeAccess=e.target.value;render();});
    $('report-form')?.addEventListener('submit',e=>{e.preventDefault();state.reportFilter=Object.fromEntries(new FormData(e.target));loadReport();});
  }
  function showEmployee(id){const e=state.data.employees.find(x=>x.enrollment_id===id);if(!e)return;show('Una persona, muchos buenos momentos.',`<div class="detail-person"><span class="avatar big">${esc(initials(e.first_name,e.last_name))}</span><div><h3>${esc(e.first_name+' '+e.last_name)}</h3><p>${esc(e.email)}</p></div></div><div class="row" style="margin-top:15px">${badge(e.status)} ${badge(e.access_status)}</div><div class="detail-list">${field('Identificación',e.person_identification)}${field('Beneficio',e.program_name)}${e.department?field('Departamento',e.department):''}${e.cost_center?field('Centro de costo',e.cost_center):''}${e.invitation_expires_at&&e.access_status!=='activated'?field('Invitación válida hasta',dateTime(e.invitation_expires_at)):''}${field('Inicio',day(e.starts_on))}${field('Fin',day(e.ends_on))}${field('Saldo individual',e.balance===null?'Cuenta no exclusiva o por configurar':money(e.balance))}${field('Próxima recarga',e.funding_ready?'Elegible actualmente':'No elegible actualmente')}</div>${notice('Una pausa bloquea el uso de este beneficio y la inclusión en nuevas recargas. Conserva los movimientos, el saldo y las solicitudes ya preparadas.')}${state.data.capabilities.manageEmployees&&e.status!=='ended'?`${state.data.capabilities.manageEmployees&&e.status==='active'&&e.access_status!=='activated'&&e.balance!==null?`<div class="section-gap">${notice('Comparte una invitación personal para que el colaborador active su acceso. Cada enlace vence a las 72 horas.')}<button class="btn full" data-invite="${esc(e.enrollment_id)}">${icon('mail')}${e.access_status==='invited'?'Renovar invitación':'Crear invitación'}</button></div>`:''}<div class="form-actions"><button class="btn ${e.status==='active'?'light':'green'}" data-enrollment="${esc(e.enrollment_id)}">${icon(e.status==='active'?'pause':'check')}${e.status==='active'?'Pausar beneficio':'Reactivar beneficio'}</button></div>`:''}`);}
  function editEnrollment(id){const e=state.data.employees.find(x=>x.enrollment_id===id);if(!e)return;const next=e.status==='active'?'suspended':'active',label=next==='suspended'?'Pausar beneficio':'Reactivar beneficio';show(label,`<p class="sheet-sub">${esc(e.first_name+' '+e.last_name)} · ${esc(e.program_name)}</p><form id="enrollment-form">${notice(next==='suspended'?'El colaborador dejará de usar este beneficio y de entrar en nuevas recargas. Las recargas ya solicitadas conservan su detalle.':'El colaborador volverá a usar el beneficio cuando cumpla su vigencia y las reglas del programa.')}<label class="form-field">Motivo del cambio<input class="input" name="reason" required minlength="5" maxlength="400" placeholder="Ej. Pausa temporal de la participación"></label>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button type="submit" class="btn ${next==='active'?'green':''}">${label}</button></div></form>`);$('enrollment-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target,async()=>{await post('update-enrollment',{enrollment_id:id,status:next,reason:new FormData(e.target).get('reason')});close();await loadAll();toast(next==='suspended'?'Beneficio pausado. El historial y el saldo se conservan.':'Beneficio reactivado.');});});}
  function editProgram(id){const p=state.data.programs.find(x=>x.id===id);if(!p||!state.data.capabilities.manageBenefits)return;show('Un beneficio a tu medida.',`<p class="sheet-sub">${esc(p.name)} · Configura la referencia para preparar las recargas de tu equipo.</p><form id="program-form"><label class="form-field">Monto por colaborador (USD)<input class="input" name="allocation_amount" type="number" inputmode="decimal" min="0.01" max="1000000" step="0.01" required value="${Number(p.allocation_amount)}"></label><label class="form-field">Frecuencia<select class="input" name="allocation_frequency">${Object.entries(frequency).map(([v,n])=>`<option value="${v}" ${v===p.allocation_frequency?'selected':''}>${n}</option>`).join('')}</select></label><label class="form-field">Política de acumulación<select class="input" name="rollover_policy">${Object.entries(rollover).map(([v,n])=>`<option value="${v}" ${v===p.rollover_policy?'selected':''}>${n}</option>`).join('')}</select><small>La configuración no modifica saldos existentes. Las vigencias de las asignaciones se gestionan con ReVale.</small></label>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button class="btn" type="submit">Guardar beneficio</button></div></form>`);$('program-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target,async()=>{await post('update-program',{program_id:id,...Object.fromEntries(new FormData(e.target))});close();await loadAll();toast('Beneficio actualizado.');});});}
  async function editRules(id){const p=state.data.programs.find(x=>x.id===id);if(!p)return;show('Reglas de uso','<div class="empty"><span class="spinner"></span><p>Cargando las condiciones del beneficio…</p></div>');const d=await api('rules',{program_id:id});if(!$('sheet').open)return;const rules=d.rules,can=state.data.capabilities.manageBenefits,max=rules.find(r=>r.rule_type==='max_transaction_amount')?.rule_value?.amount??'',daily=rules.find(r=>r.rule_type==='daily_limit')?.rule_value?.amount??'',allowed=rules.find(r=>r.rule_type==='merchant_allowlist')?.rule_value?.merchant_ids||[],extra=rules.filter(r=>!['max_transaction_amount','daily_limit','merchant_allowlist'].includes(r.rule_type));show('Reglas claras. Buenos momentos.',`<p class="sheet-sub">${esc(p.name)} · Estas condiciones se revisan antes de aprobar cada consumo.</p><form id="rules-form"><div class="form-grid"><label class="form-field">Máximo por compra (USD)<input class="input" name="max_transaction_amount" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" placeholder="Sin límite adicional" value="${esc(max)}" ${can?'':'disabled'}><small>Deja vacío para quitar este límite.</small></label><label class="form-field">Máximo por día (USD)<input class="input" name="daily_limit" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" placeholder="Sin límite adicional" value="${esc(daily)}" ${can?'':'disabled'}><small>Por colaborador, según la regla del programa.</small></label></div><span class="section-label">Restaurantes</span><label class="radio-row"><input type="radio" name="restaurant_mode" value="all" ${!allowed.length?'checked':''} ${can?'':'disabled'}>Toda la red habilitada</label><label class="radio-row"><input type="radio" name="restaurant_mode" value="selected" ${allowed.length?'checked':''} ${can?'':'disabled'}>Elegir restaurantes</label><div id="merchant-checks" class="check-grid ${allowed.length?'':'hidden'}">${state.data.merchants.map(m=>`<label class="check-row"><input type="checkbox" name="merchant" value="${esc(m.id)}" ${allowed.includes(m.id)?'checked':''} ${can?'':'disabled'}>${esc(m.name)}</label>`).join('')}</div>${extra.length?`<div class="section-gap">${notice('Este beneficio tiene restricciones adicionales de comercios o sucursales administradas por ReVale. Se conservarán al guardar.')}</div>`:''}${formErrorSlot}<div class="form-actions"><button type="button" class="btn light" data-action="close">${can?'Cancelar':'Cerrar'}</button>${can?'<button class="btn" type="submit">Guardar reglas</button>':''}</div></form>`,true);document.querySelectorAll('[name="restaurant_mode"]').forEach(r=>r.addEventListener('change',()=>{$('merchant-checks').classList.toggle('hidden',r.value==='all');}));$('rules-form').addEventListener('submit',e=>{e.preventDefault();if(!can)return;submit(e.target,async()=>{const f=new FormData(e.target),ids=f.get('restaurant_mode')==='all'?[]:f.getAll('merchant');if(f.get('restaurant_mode')==='selected'&&!ids.length)throw new Error('Selecciona al menos un restaurante o elige toda la red.');await post('save-rules',{program_id:id,max_transaction_amount:f.get('max_transaction_amount'),daily_limit:f.get('daily_limit'),merchant_ids:ids});close();toast('Reglas guardadas. Se aplican a los próximos consumos.');});});}
  function onboardingProgram(selected=''){return `<label class="form-field">Beneficio<select class="input" name="program_id" required>${state.data.programs.filter(p=>p.active).map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`;}
  function canOnboard(){if(!state.data.capabilities.manageEmployees)return false;if(!state.data.programs.some(p=>p.active)){toast('Activa un beneficio con ReVale antes de incorporar al equipo.');return false;}return true;}
  function employeeForm(values={}){
    if(!canOnboard())return;
    show('Una nueva persona. Más buenos momentos.',`<p class="sheet-sub">Incorpora al colaborador y después comparte su invitación personal.</p><form id="employee-create-form">${onboardingProgram(state.onboarding?.program?.id)}<div class="form-grid">${[['Nombres','first_name','text',80],['Apellidos','last_name','text',80],['Correo de acceso','email','email',254],['Identificación','person_identification','text',30]].map(([label,name,type,max])=>`<label class="form-field">${label}<input class="input" name="${name}" type="${type}" maxlength="${max}" required value="${esc(values[name]||'')}" ${name==='person_identification'?'placeholder="Cédula o pasaporte"':''}></label>`).join('')}<label class="form-field">Fecha de inicio<input class="input" name="starts_on" type="date" required value="${esc(values.starts_on||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()))}"></label><label class="form-field">Monto habitual (USD)<input class="input" name="allocation_amount" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" placeholder="Monto del beneficio" value="${esc(values.allocation_amount??'')}"><small>Se propone al preparar recargas. Puedes dejarlo vacío.</small></label><label class="form-field">Departamento <small>Opcional</small><input class="input" name="department" maxlength="80" value="${esc(values.department||'')}"></label><label class="form-field">Centro de costo <small>Opcional</small><input class="input" name="cost_center" maxlength="80" value="${esc(values.cost_center||'')}"></label></div>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button class="btn" type="submit">Revisar datos ${icon('arrow')}</button></div></form>`,true);
    $('employee-create-form').addEventListener('submit',event=>{event.preventDefault();submit(event.target,async()=>{const {program_id,...row}=Object.fromEntries(new FormData(event.target));const d=await post('preview-employees',{program_id,rows:[row]});state.onboarding={...d,mode:'single',request_id:crypto.randomUUID()};reviewEmployees();});});
  }
  function employeeImport(){
    if(!canOnboard())return;
    show('Tu equipo, de una sola vez.',`<p class="sheet-sub">Sube un Excel o CSV. Revisaremos los datos antes de incorporar a nadie.</p><form id="employee-import-form">${onboardingProgram(state.onboarding?.program?.id)}<a class="template-link" href="/empresas/plantilla-colaboradores.xlsx" download>${icon('download')}Descargar plantilla Excel <span>8 columnas · lista para completar</span></a><label class="upload-box">${icon('team')}<b>Selecciona el archivo de tu equipo</b><span>Excel (.xlsx) o CSV · hasta 500 personas · máximo 2 MB</span><input id="employee-file" type="file" accept=".xlsx,.csv" required></label><p class="report-note">Nombres, apellidos, correo e identificación son obligatorios. Conserva las identificaciones como texto para mantener sus ceros iniciales. Cada persona necesita un correo propio.</p>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button class="btn" type="submit">Revisar archivo ${icon('arrow')}</button></div></form>`,true);
    $('employee-import-form').addEventListener('submit',event=>{event.preventDefault();submit(event.target,async()=>{const file=$('employee-file').files[0];if(!file||file.size>2000000)throw new Error('Selecciona un archivo de hasta 2 MB.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('No pudimos leer el archivo.'));reader.readAsDataURL(file);});const d=await post('preview-employees',{program_id:event.target.elements.program_id.value,file:{name:file.name,content}});state.onboarding={...d,mode:'file',filename:file.name,request_id:crypto.randomUUID()};reviewEmployees();});});
  }
  function reviewEmployees(){const o=state.onboarding;if(!o)return;show('Revisa antes de incorporar.',`<p class="sheet-sub">${esc(o.program.name)}${o.filename?' · '+esc(o.filename):''}</p><div class="import-summary"><div><b>${o.summary.new}</b><span>Por incorporar</span></div><div><b>${o.summary.existing}</b><span>Ya vinculados</span></div><div class="${o.summary.errors?'has-errors':''}"><b>${o.summary.errors}</b><span>Por corregir</span></div></div><form id="employee-review-form"><div class="import-review">${o.rows.map(r=>`<div class="import-row ${r.status==='error'?'invalid':''}"><span class="row-number">${r.row}</span><div><b>${esc(r.first_name+' '+r.last_name)}</b><small>${esc(r.email)} · ${esc(r.person_identification)}</small>${r.errors.map(error=>`<p class="row-error">${esc(error)}</p>`).join('')}</div><span class="badge ${r.status==='error'?'off':r.status==='existing'?'wait':''}">${r.status==='error'?'Revisar':r.status==='existing'?'Ya vinculado':'Nuevo'}</span></div>`).join('')}</div><div class="section-gap">${notice(o.summary.errors?'Corrige las filas señaladas y vuelve a revisar. La carga se confirma completa.':o.summary.existing?'Las personas ya vinculadas conservan sus datos y beneficios. Se incorporarán únicamente las nuevas.':'Se crearán sus cuentas de beneficio con saldo inicial cero. Después podrás compartir las invitaciones.')}</div>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="employee-back">${o.summary.errors?'Corregir datos':'Volver'}</button><button class="btn" type="submit" ${o.summary.errors||!o.summary.new?'disabled':''}>Incorporar ${o.summary.new===1?'colaborador':o.summary.new+' colaboradores'} ${icon('check')}</button></div></form>`,true);
    $('employee-review-form').addEventListener('submit',event=>{event.preventDefault();submit(event.target,async()=>{const result=await post('import-employees',{program_id:o.program.id,rows:o.rows,request_id:o.request_id});state.onboarding=null;state.view='employees';state.employeeAccess='all';state.employeeFilter='all';state.employeeProgram='';state.search='';history.replaceState(null,'','#employees');await loadAll();show('Tu equipo ya está aquí.',`<div class="success-symbol">${icon('check')}</div><p class="sheet-sub">${result.created} ${result.created===1?'colaborador incorporado':'colaboradores incorporados'}${result.existing?' · '+result.existing+' ya vinculados':''}.</p>${notice('El siguiente paso es crear y compartir una invitación personal desde la ficha de cada colaborador. El enlace permite elegir su contraseña y activar el acceso.')}<div class="form-actions"><button class="btn" data-action="pending-access">Revisar accesos ${icon('arrow')}</button></div>`);});});
  }
  async function inviteEmployee(id){
    const employee=state.data.employees.find(e=>e.enrollment_id===id);if(!employee)return;
    if(employee.access_status==='invited'&&!$('confirm-renew-invite')){show('¿Crear una nueva invitación?',`<p class="sheet-sub">El enlace anterior de ${esc(employee.first_name)} dejará de funcionar. Comparte el nuevo enlace únicamente con esta persona.</p><div class="form-actions"><button class="btn light" data-action="close">Cancelar</button><button class="btn" id="confirm-renew-invite" data-invite="${id}">Crear nuevo enlace</button></div>`);return;}
    const invitation=await post('invite-employee',{enrollment_id:id});await loadAll();
    show('Su primer buen momento empieza aquí.',`<div class="detail-person"><span class="avatar big green">${esc(initials(employee.first_name,employee.last_name))}</span><div><h3>${esc(employee.first_name+' '+employee.last_name)}</h3><p>${esc(invitation.email)}</p></div></div><p class="sheet-sub">Comparte este enlace directamente con el colaborador. Elegirá su contraseña y activará su cuenta.</p><label class="form-field">Invitación personal<input id="invitation-link" class="input reference-input" readonly value="${esc(invitation.url)}"></label>${field('Válida hasta',dateTime(invitation.expires_at))}<p class="report-note">El enlace funciona una sola vez. Desde esta pantalla se prepara para compartir; no se envía un correo automáticamente.</p><div class="form-actions"><button class="btn light" data-action="close">Cerrar</button><button class="btn" data-action="copy-invitation">${icon('mail')}Copiar invitación</button></div>`);
  }
  const eligibleFor=id=>state.data.employees.filter(e=>e.program_id===id&&e.funding_ready);
  function fundingStepper(review=false){return `<div class="stepper"><span class="${review?'':'current'}"><b>1</b>Preparar</span>${icon('chevron')}<span class="${review?'current':''}"><b>2</b>Revisar</span>${icon('chevron')}<span><b>3</b>Enviar a aprobación</span></div>`;}
  function fundingPeople(programId,previous=null){return eligibleFor(programId).map(e=>{const old=previous?.find(p=>p.enrollment_id===e.enrollment_id);return {...e,selected:previous?Boolean(old):true,amount:old?.amount??e.suggested_amount??state.data.programs.find(p=>p.id===programId).allocation_amount??0};});}
  function newFunding(){if(!state.data.capabilities.requestFunding)return;const p=state.data.programs.find(x=>x.active);if(!p){toast('Tu empresa necesita un beneficio activo para preparar una recarga.');return;}state.request={request_id:crypto.randomUUID(),program_id:p.id,amount_per_employee:p.allocation_amount,external_reference:'',people:fundingPeople(p.id)};fundingForm();}
  async function repeatFunding(id){
    if(!state.data.capabilities.requestFunding)return;
    const d=await api('funding-detail',{id}),fresh=await api('employees');state.data.employees=fresh.employees;
    const p=state.data.programs.find(x=>x.id===d.batch.program_id&&x.active);if(!p)throw new Error('El beneficio original ya no está activo. Prepara una recarga con otro beneficio.');
    const people=fundingPeople(p.id,d.items),included=new Set(people.map(e=>e.enrollment_id));
    state.request={request_id:crypto.randomUUID(),program_id:p.id,amount_per_employee:p.allocation_amount,external_reference:'',people,source_batch_id:id,source_reference:d.batch.external_reference||day(d.batch.created_at),excluded:d.items.filter(i=>!included.has(i.enrollment_id)).length};fundingForm();
  }
  function fundingEditorRows(){const f=state.request,q=searchText($('fund-search')?.value||'');return f.people.filter(e=>searchText(e.first_name+' '+e.last_name+' '+e.department+' '+e.cost_center).includes(q)).map(e=>`<div class="fund-person"><label class="fund-select"><input type="checkbox" data-fund-person="${e.enrollment_id}" ${e.selected?'checked':''}><span class="avatar">${esc(initials(e.first_name,e.last_name))}</span><span><b>${esc(e.first_name+' '+e.last_name)}</b><small>${esc([e.department,e.cost_center].filter(Boolean).join(' · ')||e.email)}${e.access_status!=='activated'?' · Cuenta por activar':''}</small></span></label><label class="person-amount"><span>USD</span><input class="input money" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" data-fund-amount="${e.enrollment_id}" aria-label="Monto para ${esc(e.first_name+' '+e.last_name)}" value="${esc(e.amount)}" ${e.selected?'':'disabled'}></label></div>`).join('')||empty('No hay colaboradores para esta selección.','Revisa su estado y fecha de inicio.','team');}
  function fundingTotal(){const selected=state.request.people.filter(e=>e.selected),total=selected.reduce((sum,e)=>sum+Math.round(Number(e.amount||0)*100),0)/100;$('fund-count').textContent=selected.length+' '+(selected.length===1?'colaborador seleccionado':'colaboradores seleccionados');$('fund-total').textContent=money(total);}
  function fundingForm(){const f=state.request;if(!f)return;show('Buenos momentos en camino.',`${fundingStepper()}<p class="sheet-sub">Elige a tu equipo y ajusta el monto de cada persona.</p>${f.source_batch_id?notice('Estás repitiendo '+esc(f.source_reference)+'. '+(f.excluded?f.excluded+' personas ya no son elegibles. ':'')+'Las incorporaciones nuevas quedan sin seleccionar para que puedas revisarlas.'):''}<form id="funding-form"><div class="form-grid"><label class="form-field">Beneficio<select class="input" name="program_id" id="fund-program">${state.data.programs.filter(p=>p.active).map(p=>`<option value="${esc(p.id)}" ${p.id===f.program_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="form-field">Referencia de tu empresa<input class="input" name="external_reference" maxlength="120" required placeholder="Ej. Alimentación de noviembre" value="${esc(f.external_reference)}"></label></div><details class="common-amount"><summary>Ajustar un monto común para los seleccionados</summary><div class="amount-toolbar"><label class="form-field">Monto común (USD)<input class="input" id="fund-amount" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" value="${Number(f.amount_per_employee||0)}"></label><button class="btn light" type="button" data-action="fund-apply-amount">Aplicar a seleccionados</button></div></details><div class="roster-tools"><label class="search">${icon('search')}<input id="fund-search" type="search" aria-label="Buscar en la recarga" placeholder="Nombre, departamento o centro de costo"></label><button class="text-btn" type="button" data-action="fund-select-all">Seleccionar todos</button><button class="text-btn" type="button" data-action="fund-select-none">Quitar todos</button></div><div id="fund-people" class="fund-roster">${fundingEditorRows()}</div><div class="funding-footer"><div class="detail-total"><span id="fund-count"></span><strong class="money" id="fund-total"></strong></div>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="close">Cancelar</button><button type="submit" class="btn">Revisar recarga ${icon('arrow')}</button></div></div></form>`,true);
    fundingTotal();
    $('fund-program').addEventListener('change',()=>{f.program_id=$('fund-program').value;f.people=fundingPeople(f.program_id);f.amount_per_employee=state.data.programs.find(p=>p.id===f.program_id).allocation_amount;f.external_reference=$('funding-form').elements.external_reference.value;delete f.source_batch_id;fundingForm();});
    $('fund-search').addEventListener('input',()=>{$('fund-people').innerHTML=fundingEditorRows();});
    $('fund-people').addEventListener('input',event=>{const el=event.target;if(el.dataset.fundAmount){f.people.find(e=>e.enrollment_id===el.dataset.fundAmount).amount=el.value;fundingTotal();}});
    $('fund-people').addEventListener('change',event=>{const el=event.target;if(el.dataset.fundPerson){f.people.find(e=>e.enrollment_id===el.dataset.fundPerson).selected=el.checked;$('fund-people').innerHTML=fundingEditorRows();fundingTotal();}});
    $('funding-form').addEventListener('submit',event=>{event.preventDefault();f.external_reference=event.target.elements.external_reference.value.trim();const people=f.people.filter(e=>e.selected);if(!people.length){formError(new Error('Selecciona al menos un colaborador.'));return;}if(people.some(e=>!Number.isFinite(Number(e.amount))||Number(e.amount)<=0||Number(e.amount)>1000000||Math.round(Number(e.amount)*100)!==Math.round(Number(e.amount)*10000)/100)){formError(new Error('Revisa los montos: deben ser positivos, con hasta dos decimales.'));return;}reviewFunding();});
  }
  function reviewFunding(){const f=state.request,people=f.people.filter(e=>e.selected),program=state.data.programs.find(p=>p.id===f.program_id),total=people.reduce((sum,e)=>sum+Math.round(Number(e.amount)*100),0)/100,pending=people.filter(e=>e.access_status!=='activated').length;
    show('Todo listo para revisar.',`${fundingStepper(true)}<p class="sheet-sub">Revisa el detalle que aprobarán tus compañeros de empresa.</p><form id="funding-review"><div class="review-heading"><span class="benefit-symbol">${icon('gift')}</span><div><b>${esc(program.name)}</b><p>${esc(f.external_reference)}</p></div></div><div class="detail-total"><span>${people.length} colaboradores · Total a solicitar</span><strong class="money">${money(total)}</strong></div><div class="review-roster">${people.map(e=>`<div class="detail-row"><span>${esc(e.first_name+' '+e.last_name)}<small>${esc(e.cost_center||e.department||'')}</small></span><b class="money">${money(e.amount)}</b></div>`).join('')}</div>${pending?notice(pending+' personas aún deben activar su acceso. Podrán usar el beneficio cuando completen la activación.',true):''}<div class="section-gap">${notice('Esta recarga requiere <b>'+ (total>state.data.policy.threshold?'2 aprobaciones independientes':'1 aprobación independiente')+'</b> dentro de tu empresa. Quien prepara no puede aprobar. Después, ReVale verifica los fondos y realiza la acreditación.')}</div>${formErrorSlot}<div class="form-actions"><button class="btn light" type="button" data-action="fund-back">Volver</button><button class="btn" type="submit">Solicitar aprobación ${icon('shield')}</button></div></form>`,true);
    $('funding-review').addEventListener('submit',e=>{e.preventDefault();submit(e.target,async()=>{const d=await post('request-funding',{request_id:f.request_id,program_id:f.program_id,external_reference:f.external_reference,source_batch_id:f.source_batch_id,expected_employee_count:people.length,items:people.map(e=>({enrollment_id:e.enrollment_id,account_id:e.account_id,amount:Number(e.amount)}))});state.request=null;close();state.view='funding';history.replaceState(null,'','#funding');await loadAll();await showFunding(d.batch.id);toast(d.idempotent?'Esta solicitud ya estaba registrada.':'Solicitud enviada a aprobación de tu empresa.');});});
  }
  async function showFunding(id){
    state.activeApproval=null;show('Detalle de la recarga','<div class="empty"><span class="spinner"></span><p>Consultando el estado de tu recarga…</p></div>');
    const d=await api('funding-detail',{id});if(!$('sheet').open)return;
    const b=d.batch,a=d.approval,cancelled=b.status==='cancelled'||['company_rejected','company_cancelled'].includes(b.progress),pending=b.progress==='company_pending',fullyReceived=Number(b.cash_net)>=Number(b.item_total),allocated=b.progress==='credited';
    const next=cancelled?['Esta solicitud no continuará',b.unallocated_cash>0?'Hay fondos recibidos sin asignar. Coordina con ReVale su devolución; las decisiones y movimientos permanecen en el historial.':'El detalle y las decisiones se conservan. Puedes repetir la recarga y revisar los cambios antes de enviarla otra vez.']:pending?['Siguiente paso: aprobación de tu empresa',a?.blocked?'Revisa el equipo aprobador. Hace falta otra persona habilitada para completar las decisiones requeridas.':'Administración o Finanzas debe completar '+a.remaining_approvals+' '+(a.remaining_approvals===1?'aprobación':'aprobaciones')+' antes de continuar con ReVale.']:b.progress==='awaiting_preparation'?['Siguiente paso: preparar el detalle','ReVale debe completar el detalle de colaboradores de esta solicitud antes de acreditar.']:allocated?['Tu equipo ya recibió el beneficio','Puedes consultar los montos acreditados por persona y preparar tu próxima recarga.']:b.funding_gap>0?['Siguiente paso: completar los fondos','Faltan '+money(b.funding_gap)+' para cubrir esta solicitud. Usa la referencia ReVale al transferir y coordina con tu contacto de ReVale los datos bancarios y la validación.']:['Siguiente paso: aprobación de ReVale','Los fondos están identificados. ReVale debe completar sus controles financieros y la acreditación.'];
    show(b.external_reference||'Detalle de la recarga',`<p class="sheet-sub">${esc(b.program_name)} · ${esc(day(b.created_at))}</p>${badge(b.progress||b.status)}<div class="detail-total"><span>Solicitado para ${Number(b.employee_count)} colaboradores</span><strong class="money">${money(b.amount)}</strong></div><div class="next-step"><span>${icon(allocated?'check':cancelled?'info':'arrow')}</span><div><h3>${esc(next[0])}</h3><p>${esc(next[1])}</p></div></div>
      <details class="help-details" ${pending?'open':''}><summary>Colaboradores de esta solicitud (${d.items.length})</summary><div class="approval-roster">${d.items.map(i=>`<div class="detail-row"><span>${esc(i.first_name+' '+i.last_name)}<small>${i.status==='allocated'?'Acreditado':cancelled?'Solicitud cerrada':'Por acreditar'}</small></span><b>${money(i.amount)}</b></div>`).join('')}</div></details>
      ${approvalBlock(a)}
      ${cancelled?'':`<div class="timeline"><div class="timeline-item done"><span>${icon('check')}</span><div><b>Solicitud registrada</b><p>${esc(dateTime(b.created_at))} · Tu empresa</p></div></div>${a?`<div class="timeline-item ${a.status==='approved'?'done':''}"><span>${a.status==='approved'?icon('check'):'2'}</span><div><b>${a.status==='approved'?'Aprobada por tu empresa':'Aprobación interna pendiente'}</b><p>${a.approved_count} de ${a.required_approvals} decisiones · Tu empresa</p></div></div>`:''}<div class="timeline-item ${fullyReceived?'done':''}"><span>${fullyReceived?icon('check'):a?'3':'2'}</span><div><b>${fullyReceived?'Fondos completos':Number(b.received_amount)>0?'Fondos recibidos parcialmente':'Transferencia por verificar'}</b><p>${money(b.cash_net)} netos identificados · Validación bancaria de ReVale</p></div></div><div class="timeline-item ${allocated?'done':''}"><span>${allocated?icon('check'):a?'4':'3'}</span><div><b>${allocated?'Beneficio acreditado':'Aprobación y acreditación'}</b><p>${money(b.allocated_amount)} asignados de ${money(b.item_total)} · ReVale</p></div></div></div>`}
      <div class="detail-list">${field('Recibido neto',money(b.cash_net))}${field('Ya acreditado',money(b.allocated_amount))}${field('Recibido por acreditar',money(b.unallocated_cash))}${!cancelled?field('Falta por recibir',money(b.funding_gap)):''}</div>${d.receipts.length?`<span class="section-label">Transferencias identificadas</span>${d.receipts.map(r=>field(r.bank_reference,money(r.amount)+' · '+day(r.bank_posted_on))).join('')}`:''}${d.refunds.length?`<span class="section-label">Devoluciones a tu empresa</span>${d.refunds.map(r=>field(r.bank_reference,money(r.amount)+' · '+day(r.bank_posted_on))).join('')}`:''}<label class="form-field section-gap">Referencia ReVale<input class="input reference-input" readonly value="${esc(b.id)}" aria-label="Referencia de la recarga"><small>${pending?'Primero completa la aprobación interna de tu empresa.':cancelled?'Referencia para consultar el historial.':'Incluye esta referencia al coordinar tu transferencia.'}</small></label><div class="form-actions"><button class="btn light" data-action="close">Cerrar</button>${state.data.capabilities.requestFunding?`<button class="btn" data-repeat-funding="${esc(b.id)}">${icon('history')}Repetir recarga</button>`:''}</div>`,true);
  }
  function showReport(id){const t=state.report?.items.find(x=>x.id===id);if(!t)return;show('Cada consumo, en detalle.',`<div class="detail-total"><span>${esc(t.merchant_name)}</span><strong class="money">${money(t.amount)}</strong></div>${badge(t.status)}<div class="detail-list">${field('Colaborador',t.first_name+' '+t.last_name)}${field('Beneficio',t.program_name)}${field('Sucursal',t.location_name||'—')}${field('Aprobado',dateTime(t.approved_at))}${t.reversed_at?field('Devuelto',dateTime(t.reversed_at)):''}${field('Transacción',t.id)}${field('Factura',t.invoice_status==='matched'?'Registrada por el comercio':'Pendiente del comercio')}${t.invoice_matched_at?field('Registro de factura',dateTime(t.invoice_matched_at)):''}</div>${notice('La factura del restaurante corresponde al colaborador. Este detalle permite dar seguimiento a su registro y no reemplaza el documento fiscal.')}<div class="form-actions"><button class="btn light" data-action="close">Cerrar</button></div>`);}
  function downloadCSV(name,rows){const safe=value=>{let s=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportEmployees(){downloadCSV('ReVale-colaboradores.csv',[['Nombre','Correo','Identificación','Beneficio','Estado','Acceso','Departamento','Centro de costo','Saldo individual USD','Inicio','Fin'],...filteredEmployees().map(e=>[e.first_name+' '+e.last_name,e.email,e.person_identification,e.program_name,{active:'Activo',suspended:'Pausado',ended:'Finalizado'}[e.status],{activated:'Activado',invited:'Invitación vigente',expired:'Invitación vencida',not_invited:'Por invitar'}[e.access_status],e.department,e.cost_center,e.balance??'',e.starts_on,e.ends_on||''])]);toast('Directorio exportado con los filtros actuales.');}
  async function exportReport(button){if(button.disabled)return;button.disabled=true;const before=button.innerHTML;button.textContent='Preparando…';try{const query={...(Object.keys(state.reportFilter).length?state.reportFilter:state.data.period)};let r=await api('reports',query),items=[...r.items];if(r.summary.total>10000)throw new Error('El período tiene más de 10.000 consumos. Reduce el rango para exportarlo.');while(r.hasMore){r=await api('reports',{...query,offset:r.nextOffset});items.push(...r.items);if(items.length>10000)throw new Error('Reduce el período para exportar menos de 10.000 consumos.');}downloadCSV(`ReVale-consumos-${query.from}-${query.to}.csv`,[['Transacción','Colaborador','Beneficio','Restaurante','Sucursal','Aprobación (Ecuador)','Monto USD','Estado','Factura'],...items.map(t=>[t.id,t.first_name+' '+t.last_name,t.program_name,t.merchant_name,t.location_name||'',new Intl.DateTimeFormat('es-EC',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Guayaquil'}).format(new Date(t.approved_at)),t.amount,t.status==='reversed'?'Devuelto':'Aprobado',t.invoice_status==='matched'?'Registrada':'Pendiente'])]);toast('Reporte exportado.');}catch(e){handleError(e);}finally{if(button.isConnected){button.disabled=false;button.innerHTML=before;}}}
  function showAccount(){const p=state.data.principal,d=state.data;show('El espacio de tu empresa.',`<div class="detail-person"><span class="avatar big green">${esc(initials(p.displayName.split(' ')[0],p.displayName.split(' ')[1]))}</span><div><h3>${esc(p.displayName)}</h3><p>${esc(p.email)}</p></div></div><div class="detail-list">${field('Empresa',d.employer.name)}${field('RUC',d.employer.tax_id||'Por registrar')}${field('Tu rol',roleNames[p.role]||'Consulta')}</div>${notice('Cada persona tiene un acceso propio. Las acciones disponibles dependen de su rol en la empresa.')}<div class="form-actions"><button class="btn light" data-action="logout-confirm">${icon('logout')}Cerrar sesión</button></div>`);}
  function help(){show('Estamos para acompañarte.',`<p class="sheet-sub">Una gestión clara para que tu equipo disfrute más.</p>${[
    ['¿Cómo preparo una recarga?','Elige un beneficio, revisa los colaboradores elegibles y el monto por persona. Al confirmar se crea una solicitud para aprobación interna. Según el monto, requiere una o dos personas de Administración o Finanzas, distintas de quien la preparó. Después ReVale verifica los fondos y completa sus controles financieros.'],
    ['¿Quién puede hacer cada cosa?','Administración gestiona el equipo, los permisos y las reglas de aprobación. Recursos Humanos gestiona colaboradores, beneficios y prepara recargas. Finanzas prepara y aprueba recargas. Nadie puede aprobar su propia solicitud. Los permisos de consulta no permiten realizar cambios.'],
    ['¿Qué pasa al pausar un beneficio?','El colaborador deja de usar ese beneficio y no se incluye en nuevas solicitudes. Su historial y saldo se conservan; las recargas ya preparadas mantienen su detalle. Puedes reactivarlo cuando corresponda.'],
    ['¿Cómo incorporo nuevos colaboradores?','Usa Añadir colaborador o Importar equipo. Revisa los datos antes de confirmar y crea una invitación desde su ficha. Comparte el enlace directamente con esa persona para que elija su contraseña y active su cuenta.'],
    ['¿Qué contienen los reportes?','Consumos de los programas de tu empresa, fechas, restaurantes, montos, devoluciones y estado de registro de la factura. Puedes filtrar por período y exportar el detalle. El reporte no reemplaza la factura del restaurante.'],
    ['¿Necesitas ayuda con tu acceso?','Contacta al administrador de tu empresa o a tu contacto de ReVale para revisar tu usuario y sus permisos.']
  ].map(([title,copy])=>`<details class="help-details"><summary>${title}</summary><p>${copy}</p></details>`).join('')}`);}
  async function logout(){await request('/api/employer-auth?action=logout',{method:'POST',body:'{}'});sessionVersion++;state.data=null;state.report=null;state.request=null;state.search='';state.employeeFilter='all';state.employeeProgram='';state.employeeAccess='all';state.onboarding=null;state.fundingFilter='all';state.reportFilter={};state.view='home';state.team=null;state.inbox=null;state.approvalFilter='pending';close();history.replaceState(null,'',location.pathname);renderLogin();}
  document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;try{
    if(b.dataset.invite){b.disabled=true;try{return await inviteEmployee(b.dataset.invite);}finally{b.disabled=false;}}
    if(b.dataset.repeatFunding){b.disabled=true;try{return await repeatFunding(b.dataset.repeatFunding);}finally{b.disabled=false;}}
    if(b.dataset.member)return editMember(b.dataset.member);
    if(b.dataset.teamInvite){b.disabled=true;try{return await issueTeamInvite({user_id:b.dataset.teamInvite});}finally{b.disabled=false;}}
    if(b.dataset.approvalFilter){state.approvalFilter=b.dataset.approvalFilter;return await loadGovernance();}
    if(b.dataset.decision)return decisionForm(b.dataset.decision);
    if(b.dataset.nav)return await go(b.dataset.nav);
    if(b.dataset.employeeFilter){state.employeeFilter=b.dataset.employeeFilter;return render();}
    if(b.dataset.fundingFilter){state.fundingFilter=b.dataset.fundingFilter;return render();}
    if(b.dataset.employee)return showEmployee(b.dataset.employee);
    if(b.dataset.enrollment)return editEnrollment(b.dataset.enrollment);
    if(b.dataset.program)return editProgram(b.dataset.program);
    if(b.dataset.rules)return await editRules(b.dataset.rules);
    if(b.dataset.funding)return await showFunding(b.dataset.funding);
    if(b.dataset.report)return showReport(b.dataset.report);
    const a=b.dataset.action;
    if(a==='more-nav')return show('Tu espacio de empresa',`<div class="more-navigation">${navs.filter(n=>['programs','reports','team'].includes(n[0])).map(([v,i,n])=>`<button class="btn light" data-nav="${v}">${icon(i)}${n}${icon('chevron')}</button>`).join('')}</div>`);
    if(a==='team-new')return memberForm();
    if(a==='policy-edit')return policyForm();
    if(a==='governance-retry')return await loadGovernance();
    if(a==='more-approvals')return await loadGovernance(true);
    if(a==='copy-team-invitation'){try{await navigator.clipboard.writeText($('team-invitation-link').value);toast('Enlace copiado. Compártelo con la persona invitada.');}catch{$('team-invitation-link').select();toast('Selecciona y copia el enlace.');}return;}
    if(a==='close')return close();
    if(a==='help')return help();
    if(a==='account')return showAccount();
    if(a==='password'){const p=$('password');p.type=p.type==='password'?'text':'password';b.setAttribute('aria-label',p.type==='password'?'Mostrar contraseña':'Ocultar contraseña');b.innerHTML=icon(p.type==='password'?'eye':'eyeoff');return;}
    if(a==='refresh'){b.disabled=true;state.report=null;try{await loadAll();toast('Datos actualizados.');}finally{b.disabled=false;}return;}
    if(a==='employee-new')return employeeForm();
    if(a==='employee-import')return employeeImport();
    if(a==='employee-back')return state.onboarding?.mode==='file'?employeeImport():employeeForm(state.onboarding?.rows?.[0]);
    if(a==='pending-access'){state.employeeAccess='pending';return go('employees');}
    if(a==='copy-invitation'){try{await navigator.clipboard.writeText($('invitation-link').value);toast('Invitación copiada. Compártela únicamente con este colaborador.');}catch{$('invitation-link').select();toast('Selecciona y copia el enlace para compartirlo.');}return;}
    if(a==='fund-repeat-last'){b.disabled=true;try{return await repeatFunding(state.data.fundingList.funding.find(f=>f.status!=='cancelled').id);}finally{b.disabled=false;}}
    if(a==='fund-apply-amount'){const n=Number($('fund-amount').value);if(!Number.isFinite(n)||n<=0||n>1000000||Math.round(n*100)!==Math.round(n*10000)/100)return formError(new Error('Ingresa un monto positivo con hasta dos decimales.'));state.request.amount_per_employee=n;state.request.people.filter(e=>e.selected).forEach(e=>e.amount=n);$('fund-people').innerHTML=fundingEditorRows();fundingTotal();return;}
    if(a==='fund-select-all'||a==='fund-select-none'){state.request.people.forEach(e=>e.selected=a==='fund-select-all');$('fund-people').innerHTML=fundingEditorRows();fundingTotal();return;}
    if(a==='fund-new')return newFunding();
    if(a==='fund-back')return fundingForm();
    if(a==='export-employees')return exportEmployees();
    if(a==='export-report')return await exportReport(b);
    if(a==='more-report')return await loadReport(true);
    if(a==='more-funding'){b.disabled=true;try{const next=await api('funding',{offset:state.data.fundingList.nextOffset});state.data.fundingList={...next,funding:[...state.data.fundingList.funding,...next.funding]};render();}finally{b.disabled=false;}return;}
    if(a==='logout-confirm')return show('¿Cerrar tu sesión?',`<p class="sheet-sub">Podrás volver a entrar con tu correo y contraseña.</p><div class="form-actions"><button class="btn light" data-action="close">Seguir aquí</button><button class="btn" data-action="logout">Sí, cerrar sesión</button></div>`);
    if(a==='logout')return await logout();
  }catch(error){handleError(error);}});
  window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(state.data&&navs.some(n=>n[0]===v))go(v);});
  (async()=>{try{await loadAll();}catch(error){renderLogin(error.status===401?'':error.message);}})();
})();
